import{_ as t,a0 as o,w as r,s as d,I as a,x as n,a1 as p,A as i,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const M=JSON.parse('{"title":"在 Ubuntu 16.04 下随机化你的 WiFi MAC 地址 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 16.04 下随机化你的 WiFi MAC 地址 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 16.04 下随机化你的 WiFi MAC 地址 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 16.04 下随机化你的 WiFi MAC 地址 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171201 Randomize your WiFi MAC address on Ubuntu 16.04","title":"在 Ubuntu 16.04 下随机化你的 WiFi MAC 地址","tag":"201712","desc":""},"relativePath":"201712/20171201 Randomize your WiFi MAC address on Ubuntu 16.04.md","filePath":"[post].md"}'),u={name:"201712/20171201 Randomize your WiFi MAC address on Ubuntu 16.04.md"};function f(m,s,g,b,c,C){const e=o("Link");return r(),d("div",null,[s[36]||(s[36]=a("h1",{id:"在-ubuntu-16-04-下随机化你的-wifi-mac-地址",tabindex:"-1"},[n("在 Ubuntu 16.04 下随机化你的 WiFi MAC 地址 "),a("a",{class:"header-anchor",href:"#在-ubuntu-16-04-下随机化你的-wifi-mac-地址","aria-label":"Permalink to “在 Ubuntu 16.04 下随机化你的 WiFi MAC 地址”"},"​")],-1)),s[37]||(s[37]=a("blockquote",null,[a("p",null,"你的设备的 MAC 地址可以在不同的 WiFi 网络中记录你的活动。这些信息能被共享后出售，用于识别特定的个体。但可以用随机生成的伪 MAC 地址来阻止这一行为。")],-1)),s[38]||(s[38]=a("p",null,[a("img",{src:"https://www.paulfurley.com/img/captive-portal-our-hotel.gif",alt:"A captive portal screen for a hotel allowing you to log in with social media for an hour of free WiFi"})],-1)),a("p",null,[a("em",null,[s[1]||(s[1]=n("Image courtesy of ",-1)),p(e,{href:"http://cloudessa.com/products/cloudessa-aaa-and-captive-portal-cloud-service/"},{default:i(()=>[...s[0]||(s[0]=[n("Cloudessa",-1)])]),_:1})])]),s[39]||(s[39]=l('<p>每一个诸如 WiFi 或者以太网卡这样的网络设备，都有一个叫做 MAC 地址的唯一标识符，如：<code>b4:b6:76:31:8c:ff</code>。这就是你能上网的原因：每当你连上 WiFi，路由器就会用这一地址来向你接受和发送数据，并且用它来区别你和这一网络的其它设备。</p><p>这一设计的缺陷在于唯一性，不变的 MAC 地址正好可以用来追踪你。连上了星巴克的 WiFi? 好，注意到了。在伦敦的地铁上? 也记录下来。</p><p>如果你曾经在某一个 WiFi 验证页面上输入过你的真实姓名，你就已经把自己和这一 MAC 地址建立了联系。没有仔细阅读许可服务条款、你可以认为，机场的免费 WiFi 正通过出售所谓的 ‘顾客分析数据’（你的个人信息）获利。出售的对象包括酒店，餐饮业，和任何想要了解你的人。</p><p>我不想信息被记录，再出售给多家公司，所以我花了几个小时想出了一个解决方案。</p><h3 id="mac-地址不一定总是不变的" tabindex="-1">MAC 地址不一定总是不变的 <a class="header-anchor" href="#mac-地址不一定总是不变的" aria-label="Permalink to “MAC 地址不一定总是不变的”">​</a></h3><p>幸运的是，在不断开网络的情况下，是可以随机生成一个伪 MAC 地址的。</p><p>我想随机生成我的 MAC 地址，但是有三个要求：</p><ol><li>MAC 地址在不同网络中是不相同的。这意味着，我在星巴克和在伦敦地铁网络中的 MAC 地址是不相同的，这样在不同的服务提供商中就无法将我的活动系起来。</li><li>MAC 地址需要经常更换，这样在网络上就没人知道我就是去年在这儿经过了 75 次的那个人。</li><li>MAC 地址一天之内应该保持不变。当 MAC 地址更改时，大多数网络都会与你断开连接，然后必须得进入验证页面再次登陆 - 这很烦人。</li></ol><h3 id="操作网络管理器networkmanager" tabindex="-1">操作<ruby>网络管理器<rt>NetworkManager</rt></ruby> <a class="header-anchor" href="#操作网络管理器networkmanager" aria-label="Permalink to “操作网络管理器NetworkManager”">​</a></h3><p>我第一次尝试用一个叫做 <code>macchanger</code> 的工具，但是失败了。因为<ruby>网络管理器<rt>NetworkManager</rt></ruby>会根据它自己的设置恢复默认的 MAC 地址。</p>',10)),a("p",null,[s[3]||(s[3]=n("我了解到，网络管理器 1.4.1 以上版本可以自动生成随机的 MAC 地址。如果你在使用 Ubuntu 17.04 版本，你可以根据",-1)),p(e,{href:"https://gist.github.com/paulfurley/978d4e2e0cceb41d67d017a668106c53/"},{default:i(()=>[...s[2]||(s[2]=[n("这一配置文件",-1)])]),_:1}),s[4]||(s[4]=n("实现这一目的。但这并不能完全符合我的三个要求（你必须在",-1)),s[5]||(s[5]=a("ruby",null,[n("随机"),a("rt",null,"random")],-1)),s[6]||(s[6]=n("和",-1)),s[7]||(s[7]=a("ruby",null,[n("稳定"),a("rt",null,"stable")],-1)),s[8]||(s[8]=n("这两个选项之中选择一个，但没有一天之内保持不变这一选项）",-1))]),s[40]||(s[40]=l(`<p>因为我使用的是 Ubuntu 16.04，网络管理器版本为 1.2，不能直接使用高版本这一新功能。可能网络管理器有一些随机化方法支持，但我没能成功。所以我编了一个脚本来实现这一目标。</p><p>幸运的是，网络管理器 1.2 允许模拟 MAC 地址。你在已连接的网络中可以看见 ‘编辑连接’ 这一选项：</p><p><img src="https://www.paulfurley.com/img/network-manager-cloned-mac-address.png" alt="Screenshot of NetworkManager&#39;s edit connection dialog, showing a text entry for a cloned mac address"></p><p>网络管理器也支持钩子处理 —— 任何位于 <code>/etc/NetworkManager/dispatcher.d/pre-up.d/</code> 的脚本在建立网络连接之前都会被执行。</p><h3 id="分配随机生成的伪-mac-地址" tabindex="-1">分配随机生成的伪 MAC 地址 <a class="header-anchor" href="#分配随机生成的伪-mac-地址" aria-label="Permalink to “分配随机生成的伪 MAC 地址”">​</a></h3><p>我想根据网络 ID 和日期来生成新的随机 MAC 地址。 我们可以使用网络管理器的命令行工具 nmcli 来显示所有可用网络：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; nmcli connection</span></span>
<span class="line"><span>NAME                 UUID                                  TYPE             DEVICE</span></span>
<span class="line"><span>Gladstone Guest      618545ca-d81a-11e7-a2a4-271245e11a45  802-11-wireless  wlp1s0</span></span>
<span class="line"><span>DoESDinky            6e47c080-d81a-11e7-9921-87bc56777256  802-11-wireless  --</span></span>
<span class="line"><span>PublicWiFi           79282c10-d81a-11e7-87cb-6341829c2a54  802-11-wireless  --</span></span>
<span class="line"><span>virgintrainswifi     7d0c57de-d81a-11e7-9bae-5be89b161d22  802-11-wireless  --</span></span></code></pre></div><p>因为每个网络都有一个唯一标识符（UUID），为了实现我的计划，我将 UUID 和日期拼接在一起，然后使用 MD5 生成 hash 值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># eg 618545ca-d81a-11e7-a2a4-271245e11a45-2017-12-03</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; echo -n &quot;\${UUID}-$(date +%F)&quot; | md5sum</span></span>
<span class="line"><span></span></span>
<span class="line"><span>53594de990e92f9b914a723208f22b3f  -</span></span></code></pre></div><p>生成的结果可以代替 MAC 地址的最后八个字节。</p>`,10)),a("p",null,[s[10]||(s[10]=n("值得注意的是，最开始的字节 ",-1)),s[11]||(s[11]=a("code",null,"02",-1)),s[12]||(s[12]=n(" 代表这个地址是",-1)),p(e,{href:"https://en.wikipedia.org/wiki/MAC_address#Universal_vs._local"},{default:i(()=>[...s[9]||(s[9]=[n("自行指定",-1)])]),_:1}),s[13]||(s[13]=n("的。实际上，真实 MAC 地址的前三个字节是由制造商决定的，例如 ",-1)),s[14]||(s[14]=a("code",null,"b4:b6:76",-1)),s[15]||(s[15]=n(" 就代表 Intel。",-1))]),s[41]||(s[41]=l(`<p>有可能某些路由器会拒绝自己指定的 MAC 地址，但是我还没有遇到过这种情况。</p><p>每次连接到一个网络，这一脚本都会用 <code>nmcli</code> 来指定一个随机生成的伪 MAC 地址：</p><p><img src="https://www.paulfurley.com/imgterminal-window-nmcli-commands.png" alt="A terminal window show a number of nmcli command line calls"></p><p>最后，我查看了 <code>ifconfig</code> 的输出结果，我发现 MAC 地址 <code>HWaddr</code> 已经变成了随机生成的地址（模拟 Intel 的），而不是我真实的 MAC 地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; ifconfig</span></span>
<span class="line"><span>wlp1s0    Link encap:Ethernet  HWaddr b4:b6:76:45:64:4d</span></span>
<span class="line"><span>          inet addr:192.168.0.86  Bcast:192.168.0.255  Mask:255.255.255.0</span></span>
<span class="line"><span>          inet6 addr: fe80::648c:aff2:9a9d:764/64 Scope:Link</span></span>
<span class="line"><span>          UP BROADCAST RUNNING MULTICAST  MTU:1500  Metric:1</span></span>
<span class="line"><span>          RX packets:12107812 errors:0 dropped:2 overruns:0 frame:0</span></span>
<span class="line"><span>          TX packets:18332141 errors:0 dropped:0 overruns:0 carrier:0</span></span>
<span class="line"><span>          collisions:0 txqueuelen:1000</span></span>
<span class="line"><span>          RX bytes:11627977017 (11.6 GB)  TX bytes:20700627733 (20.7 GB)</span></span></code></pre></div><h3 id="脚本" tabindex="-1">脚本 <a class="header-anchor" href="#脚本" aria-label="Permalink to “脚本”">​</a></h3>`,6)),a("p",null,[s[17]||(s[17]=n("完整的脚本也可以",-1)),p(e,{href:"https://gist.github.com/paulfurley/46e0547ce5c5ea7eabeaef50dbacef3f"},{default:i(()=>[...s[16]||(s[16]=[n("在 Github 上查看",-1)])]),_:1}),s[18]||(s[18]=n("。",-1))]),s[42]||(s[42]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span># /etc/NetworkManager/dispatcher.d/pre-up.d/randomize-mac-addresses</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Configure every saved WiFi connection in NetworkManager with a spoofed MAC</span></span>
<span class="line"><span># address, seeded from the UUID of the connection and the date eg:</span></span>
<span class="line"><span># &#39;c31bbcc4-d6ad-11e7-9a5a-e7e1491a7e20-2017-11-20&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># This makes your MAC impossible(?) to track across WiFi providers, and</span></span>
<span class="line"><span># for one provider to track across days.</span></span>
<span class="line"><span></span></span>
<span class="line"><span># For craptive portals that authenticate based on MAC, you might want to</span></span>
<span class="line"><span># automate logging in :)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Note that NetworkManager &gt;= 1.4.1 (Ubuntu 17.04+) can do something similar</span></span>
<span class="line"><span># automatically.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export PATH=$PATH:/usr/bin:/bin</span></span>
<span class="line"><span></span></span>
<span class="line"><span>LOG_FILE=/var/log/randomize-mac-addresses</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo &quot;$(date): $*&quot; &gt; \${LOG_FILE}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>WIFI_UUIDS=$(nmcli --fields type,uuid connection show |grep 802-11-wireless |cut &#39;-d &#39; -f3)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>for UUID in \${WIFI_UUIDS}</span></span>
<span class="line"><span>do</span></span>
<span class="line"><span>    UUID_DAILY_HASH=$(echo &quot;\${UUID}-$(date +F)&quot; | md5sum)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    RANDOM_MAC=&quot;02:$(echo -n \${UUID_DAILY_HASH} | sed &#39;s/^\\(..\\)\\(..\\)\\(..\\)\\(..\\)\\(..\\).*$/\\1:\\2:\\3:\\4:\\5/&#39;)&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    CMD=&quot;nmcli connection modify \${UUID} wifi.cloned-mac-address \${RANDOM_MAC}&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    echo &quot;$CMD&quot; &gt;&gt; \${LOG_FILE}</span></span>
<span class="line"><span>    $CMD &amp;</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span></span></span>
<span class="line"><span>wait</span></span></code></pre></div>`,1)),a("p",null,[a("em",null,[s[21]||(s[21]=n("更新：",-1)),p(e,{href:"https://gist.github.com/paulfurley/46e0547ce5c5ea7eabeaef50dbacef3f/revisions#diff-824d510864d58c07df01102a8f53faef"},{default:i(()=>[...s[19]||(s[19]=[n("使用自己指定的 MAC 地址",-1)])]),_:1}),s[22]||(s[22]=n("可以避免和真正的 intel 地址冲突。感谢 ",-1)),p(e,{href:"https://twitter.com/fink_/status/937305600005943296"},{default:i(()=>[...s[20]||(s[20]=[n("@_fink",-1)])]),_:1})])]),s[43]||(s[43]=a("hr",null,null,-1)),a("p",null,[s[24]||(s[24]=n("via: ",-1)),p(e,{href:"https://www.paulfurley.com/randomize-your-wifi-mac-address-on-ubuntu-1604-xenial/"},{default:i(()=>[...s[23]||(s[23]=[n("https://www.paulfurley.com/randomize-your-wifi-mac-address-on-ubuntu-1604-xenial/",-1)])]),_:1})]),a("p",null,[s[28]||(s[28]=n("作者：",-1)),p(e,{href:"https://www.paulfurley.com/"},{default:i(()=>[...s[25]||(s[25]=[n("Paul M Furley",-1)])]),_:1}),s[29]||(s[29]=n(" 译者：",-1)),p(e,{href:"https://github.com/wenwensnow"},{default:i(()=>[...s[26]||(s[26]=[n("wenwensnow",-1)])]),_:1}),s[30]||(s[30]=n(" 校对：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[27]||(s[27]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[33]||(s[33]=n("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[31]||(s[31]=[n("LCTT",-1)])]),_:1}),s[34]||(s[34]=n(" 原创编译，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...s[32]||(s[32]=[n("Linux中国",-1)])]),_:1}),s[35]||(s[35]=n(" 荣誉推出",-1))])])}const w=t(u,[["render",f]]);export{M as __pageData,w as default};
